import{H as O}from"./chunk-B8sAQR8u.js";var p=[{slug:`tiky`,name:`Tiky`,statuses:[`recovering`,`closed`],featured:!0,summary:`Tiky tenía apenas 3 meses cuando una máquina le destrozó una de sus patas traseras. Fue rescatada con una fractura expuesta, atravesó internación, infección y una cirugía de amputación. Después de semanas de recuperación recibió el alta definitiva y hoy vive adoptada, rodeada de amor y acompañada por Kele.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505350/WhatsApp_Image_2026-08-23_at_13.05.56_2.jpg`,width:1600,height:900,alt:`Tiky durante su recuperación`,objectPosition:`50% 40%`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505350/WhatsApp_Image_2026-08-23_at_13.05.54.jpg`,width:700,height:1556,alt:`Tiky durante su internación veterinaria`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505349/WhatsApp_Image_2026-08-23_at_13.05.54_1.jpg`,width:900,height:1600,alt:`Tiky con sus patitas vendadas durante el tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505349/WhatsApp_Image_2026-08-23_at_13.05.54_2.jpg`,width:900,height:1600,alt:`Tiky después de la cirugía de amputación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505350/WhatsApp_Image_2026-08-23_at_13.05.55.jpg`,width:1536,height:2048,alt:`Tiky durante su recuperación luego de recibir el alta`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505349/WhatsApp_Image_2026-08-23_at_13.05.55_1.jpg`,width:900,height:1600,alt:`Tiky durante su recuperación luego de recibir el alta`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505350/WhatsApp_Image_2026-08-23_at_13.05.55_2.jpg`,width:900,height:1600,alt:`Tiky durante su recuperación luego de recibir el alta`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505350/WhatsApp_Image_2026-08-23_at_13.05.55_3.jpg`,width:900,height:1600,alt:`Tiky durante su recuperación luego de recibir el alta`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505350/WhatsApp_Image_2026-08-23_at_13.05.55_4.jpg`,width:900,height:1600,alt:`Tiky durante su recuperación luego de recibir el alta`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505349/WhatsApp_Image_2026-08-23_at_13.05.56.jpg`,width:900,height:1600,alt:`Tiky durante su recuperación luego de recibir el alta`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505349/WhatsApp_Image_2026-08-23_at_13.05.56_1.jpg`,width:900,height:1600,alt:`Tiky durante su recuperación luego de recibir el alta`}],story:[`Tiky tenía apenas 3 meses. Nació de una gata feral en el Parque Industrial y hasta ese momento nunca había conocido el calor de un hogar: su vida había sido sobrevivir.`,`A fines de julio ocurrió un accidente mientras estaba refugiada debajo de un pallet. Una máquina elevadora enganchó una de sus patitas traseras y se la destrozó. Tiky permaneció muchas horas sin recibir atención, con una fractura expuesta, dolor, tierra y una infección que avanzaba sobre su pequeño cuerpo.`,`Finalmente, uno de los trabajadores del lugar la vio y decidió actuar. El 28 de julio Tiky pudo ser rescatada e internada. Comenzó a recibir antibióticos, analgésicos y los cuidados necesarios para estabilizarla. Desde el comienzo, los veterinarios sabían que, cuando su estado lo permitiera, sería necesario amputar la patita lesionada para poder salvarle la vida.`,`Durante los días siguientes continuó internada y, aunque anímicamente se encontraba muy bien, algunos valores de sus análisis generaban preocupación. Los estudios de PCR para VIF y VILEF dieron negativos, una muy buena noticia, pero se comenzó a evaluar realizar la cirugía cuanto antes para evitar que su cuadro empeorara.`,`El 3 de agosto, durante un control, descubrieron además una herida en la otra patita que estaba supurando. Tiky terminó con ambas patitas vendadas. Aun así, seguía adelante: había sobrevivido al dolor, a la infección, al frío y al hambre, y ya estaba recibiendo cuidados y cariño.`,`El 5 de agosto finalmente se realizó la cirugía de amputación de su patita trasera izquierda. La operación salió más que bien y Tiky pudo recibir el alta. Quedó bajo el cuidado de Facu y Bel, quienes continuaron acompañándola durante su recuperación.`,`Después de la cirugía todavía necesitaba controles y medicación mientras cicatrizaban sus heridas y llegaba el momento de retirar los puntos. Día a día comenzó a mostrarse más activa, a jugar y a disfrutar de una vida completamente distinta a la que había conocido durante sus primeros meses.`,`Facu y Bel la cuidaron desde el primer día de su tránsito. Allí Tiky también encontró en Kele, otro gato adoptado, un compañero con quien compartir su nueva vida. Con el paso de los días empezó a quedar claro que aquel tránsito se estaba convirtiendo en algo mucho más grande.`,`Finalmente llegaron las noticias que cerraron la etapa más difícil de su historia: le retiraron los puntos, recibió el alta y quedó oficialmente adoptada. Tiky pasó de ser una gatita herida e invisible a convertirse en la reina de una casa donde encontró cuidados, compañía y una familia para siempre.`,`Su historia empezó con una fractura, dolor y abandono, pero terminó con una segunda oportunidad. Después de luchar para sobrevivir, Tiky pudo empezar una nueva vida rodeada del amor que durante sus primeros meses nunca había conocido.`],currentNeeds:[],updates:[{date:`2026-08-20`,title:`Alta definitiva y una familia para siempre`,paragraphs:[`Finalmente llegó uno de los días más esperados de toda la historia de Tiky: le retiraron los puntos y pudo dar por terminada la etapa más dura de su recuperación.`,`Con apenas tres meses había atravesado una fractura expuesta, infección, internación y la amputación de una de sus patas traseras. Después de todo ese camino, la pequeña luchadora recibió el alta y comenzó oficialmente una nueva etapa de su vida.`,`Y junto con el alta llegó otra noticia enorme: Tiky quedó definitivamente adoptada.`,`Desde el primer día de su tránsito, Bel, Facu y Kele la acompañaron y cuidaron permanentemente. Lo que comenzó como un lugar temporal para recuperarse terminó convirtiéndose en su hogar para siempre.`,`Tiky pasó de sobrevivir en el Parque Industrial a ser la reina de una casa, acompañada por Kele y rodeada de una familia que la cuida y la ama.`,`La rescatista destacó que todo el esfuerzo de Tiky por sobrevivir valió la pena y agradeció especialmente a Bel y Facu por transitarla, cuidarla, amarla y finalmente adoptarla.`,`En esta misma actualización informó que la deuda veterinaria general había logrado reducirse hasta aproximadamente $1.390.000 y expresó la intención de continuar bajándola durante las siguientes semanas.`]},{date:`2026-08-16`,title:`Tiky está muchísimo mejor y casi con el alta`,paragraphs:[`Tiky continúa evolucionando muy bien y, después de todo lo que atravesó, ya está casi con el alta.`,`La rescatista contó que verla recuperarse, jugar y disfrutar de la vida que merece es una de esas cosas que le recuerdan por qué vale la pena seguir luchando por cada rescate.`,`Sin embargo, también explicó que decidió frenar temporalmente el ingreso de nuevos rescates porque todavía necesita resolver o reducir significativamente la deuda veterinaria general acumulada. La intención no es dejar de ayudar, sino recuperar un poco de aire para poder volver a hacerlo cuando aparezca otro animal que necesite una oportunidad.`,`En esta publicación volvió a mencionar una deuda veterinaria general cercana a $1.500.000 y pidió colaboración para poder reducirla. Aclaró que incluso aportes pequeños pueden hacer una gran diferencia cuando muchas personas se suman.`,`También recordó que, para quienes no puedan colaborar económicamente, compartir las publicaciones es otra forma muy importante de ayudar y de llegar a más personas.`,`La publicación estuvo acompañada por un video de Tiky simplemente jugando y disfrutando de su recuperación: una gatita de apenas 3 meses empezando a vivir la vida que merece.`]},{date:`2026-08-10`,title:`Tiky sigue recuperándose súper bien`,paragraphs:[`Tiky continúa recuperándose muy bien y se la puede ver cada vez más activa y cómoda durante su recuperación.`,`En esta actualización también aparece jugando junto a su hermano Kele, una imagen que refleja cuánto cambió su realidad después de todo lo que tuvo que atravesar.`,`Ese día la rescatista realizó una nueva entrega de $350.000 en efectivo en la veterinaria y agradeció especialmente a todas las personas que hicieron posible reunir ese dinero.`,`Después de esa entrega informó que todavía quedaba un saldo veterinario general pendiente de $1.600.800,84.`,`Aunque la deuda continuaba siendo muy importante, destacó que poco a poco se iba avanzando y volvió a pedir colaboración y difusión para poder seguir reduciéndola.`,`Ver a Tiky jugar con su hermano después de la fractura, la infección, la amputación y todo el proceso de recuperación hizo que todo el esfuerzo realizado hasta ese momento valiera la pena.`]},{date:`2026-08-05`,title:`La cirugía salió más que bien`,paragraphs:[`Se realizó la cirugía de amputación de la patita trasera izquierda de Tiky y, como se esperaba, la operación salió muy bien.`,`Tiky recibió el alta y quedó bajo el cuidado de Facu y Bel, quienes la acompañan con mucho amor, responsabilidad y compromiso.`,`Durante los días siguientes debe continuar con controles y medicación hasta que puedan retirarle los puntos. Su otra patita, que también estaba lesionada, todavía necesita terminar de cicatrizar.`,`La publicación señala que Tiky fue el tercer animal rescatado del año que necesitó una cirugía de amputación, junto con Fénix (Gatoman) y Patán. En los tres casos hubo fractura expuesta e infección luego de haber pasado tiempo sin atención inmediata.`,`Además de los gastos veterinarios, la rescatista recordó que los tránsitos generan gastos de alimentación y piedritas, incluso en animales que muchas veces no llegan a aparecer en publicaciones.`,`Ese día informó que la deuda veterinaria general ya había superado los $1.500.000 y que todavía faltaba conocer el monto exacto actualizado, pese a las entregas que había logrado realizar.`]},{date:`2026-08-03`,title:`Descubrieron una lesión en la otra patita`,paragraphs:[`Durante el control matutino encontraron una herida en la otra patita de Tiky que estaba supurando un poco. Como consecuencia, quedó con ambas patitas vendadas.`,`A pesar de todo lo que había atravesado —dolor, infección, frío y hambre—, Tiky seguía adelante y ya estaba recibiendo muchos cuidados y cariño.`,`Si su evolución continuaba bien, la cirugía de amputación estaba prevista para realizarse durante esa semana.`,`La rescatista contó que ese día realizó una entrega de $240.000 en la veterinaria. Después de esa entrega, informó un saldo general pendiente de $1.416.800, al que todavía debían sumarse la cirugía y los controles de Tiky.`]},{date:`2026-07-31`,title:`Buen ánimo y nuevos estudios`,paragraphs:[`Tiky se encontraba anímicamente muy bien y se mostraba relajada incluso mientras recibía la medicación.`,`Sin embargo, algunos valores de los análisis no estaban bien, por lo que los profesionales estaban evaluando realizar la cirugía cuanto antes para evitar que su cuadro empeorara.`,`Los análisis de PCR para VIF y VILEF dieron negativos, lo que representó una muy buena noticia dentro de su evolución.`,`El día anterior la rescatista había podido realizar una entrega de $250.000 en la veterinaria. En esta actualización informó que todavía quedaban $1.352.800 de deuda veterinaria general, antes de sumar los controles y la cirugía de amputación de Tiky.`,`También contó que todavía tenía números de una rifa a la venta como otra forma de reunir fondos para seguir afrontando los gastos.`]},{date:`2026-07-28`,title:`Tiky necesitaba una oportunidad para vivir`,paragraphs:[`Tiky tenía apenas 3 meses y había nacido de una gata feral en el Parque Industrial. Nunca había conocido el calor de un hogar y su vida, hasta entonces, había sido sobrevivir.`,`Mientras estaba refugiada debajo de un pallet, una máquina elevadora enganchó su patita y se la destrozó. Permaneció muchas horas sin poder recibir ayuda.`,`Cuando finalmente uno de los trabajadores del lugar la vio y decidió actuar, Tiky tenía una fractura expuesta, mucho dolor, tierra en la herida y una infección que avanzaba sobre su cuerpo.`,`Fue internada y comenzó a recibir antibióticos, analgésicos y todos los cuidados necesarios para estabilizarla. La indicación era que, cuando su estado lo permitiera, deberían amputarle la patita para salvarle la vida.`,`En ese momento la deuda veterinaria general ascendía a $1.454.206, sin incluir todavía la internación de Tiky ni los gastos que vendrían después.`,`Además de la colaboración económica para los gastos veterinarios, en esa publicación también se pidió alimento de buena calidad y piedritas para acompañar los tránsitos.`]}],updatedAt:`2026-08-20`,seoDescription:`Conocé la historia de Tiky: rescatada con una fractura expuesta a los 3 meses, sobrevivió a una amputación, se recuperó y hoy vive adoptada con una familia para siempre.`},{slug:`maxine`,name:`Maxine`,statuses:[`memorial`],featured:!1,summary:`Maxine fue rescatada junto a sus tres bebés después de años de vida en la calle. Durante meses atravesó un complejo cuadro respiratorio y, más adelante, una grave recaída neurológica asociada a distintos diagnósticos. Fue acompañada y cuidada hasta el final, y hoy su historia forma parte de quienes recordamos en memoria.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423604/cover.jpg`,width:1600,height:900,alt:`Maxine durante los meses en los que estuvo acompañada por su familia de tránsito`,objectPosition:`50% 40%`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423604/01.jpg`,width:900,height:1600,alt:`Maxine descansando durante su recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1788112483/WhatsApp_Image_2026-08-30_at_14.54.26.jpg`,width:900,height:1600,alt:`Maxine junto a sus bebés durante su tránsito`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423604/02.jpg`,width:900,height:1600,alt:`Maxine junto a sus bebés durante su tránsito`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423604/03.jpg`,width:900,height:1600,alt:`Maxine durante uno de sus tratamientos veterinarios`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/04.jpg`,width:900,height:1600,alt:`Maxine durante su internación veterinaria`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/05.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423604/06.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/07.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/08.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/09.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423606/10.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423606/11.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/12.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/13.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/14.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/15.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/16.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787423605/17.jpg`,width:900,height:1600,alt:`Maxine acompañada durante la etapa final de su tratamiento`}],story:[`Maxine fue rescatada en febrero de 2026 junto a sus tres bebés. Había pasado años en la calle y llegó con numerosas dificultades respiratorias. Después del rescate pudo ir a un tránsito, donde empezó a conocer la tranquilidad de un hogar y a recibir los cuidados que necesitaba mientras continuaba criando a sus pequeños.`,`A fines de marzo comenzó un tratamiento para sus complicaciones respiratorias. Sus bebés también habían llegado afectados, pero fueron mejorando poco a poco. Maxine, en cambio, continuaba con mucha mucosidad y necesitaba controles frecuentes. Durante abril atravesó nuevos episodios respiratorios, recibió medicación y le realizaron placas para evaluar su evolución.`,`Como el cuadro persistía a pesar del tratamiento y llegó a despedir mucosidad con sangre, los veterinarios indicaron estudios más profundos. Se planificaron un lavaje nasal, una laringoscopia, hemogramas y PCR. En los estudios realizados durante abril, las PCR para VIF y VILEF dieron negativas, mientras que Maxine dio positiva a micoplasma. Se indicó un tratamiento de aproximadamente 30 días.`,`Mientras tanto, sus bebés empezaron a comer por su cuenta y se preparaban para continuar sus vidas con sus familias. Eso permitió concentrar cada vez más la atención en Maxine. A fines de abril también le realizaron una ecografía porque su abdomen se veía distendido. Se había sospechado una nueva preñez, pero el estudio indicó que la distensión estaba relacionada con la cantidad de alimento que ingería. Después de años buscando qué comer, Maxine comía con enorme entusiasmo, por lo que se recomendó mantener la cantidad diaria pero repartirla en varias porciones.`,`A comienzos de mayo seguía medicada con doxiciclina, tenía buen apetito y su recuperación avanzaba lentamente. Si todo evolucionaba bien, la intención era castrarla una vez finalizado el tratamiento. Sin embargo, los problemas respiratorios nunca desaparecieron por completo: la mucosidad continuó durante los meses siguientes y se había recomendado realizar una rinoscopia.`,`Antes de que ese estudio pudiera concretarse, en julio su estado cambió abruptamente. El 23 de julio se informó que había comenzado con fiebre y, con el correr de las horas, desarrolló síntomas neurológicos que obligaron a internarla. Se iniciaron múltiples estudios; en ese momento se había podido descartar un ACV, pero todavía no existía un diagnóstico definitivo.`,`Los resultados que llegaron durante los días siguientes mostraron un cuadro mucho más complejo de lo esperado. Maxine dio positiva a VILEF —leucemia felina— y a micoplasma, asociado en las publicaciones a una anemia muy importante. Más adelante también dio positiva a toxoplasmosis, uno de los resultados utilizados para explicar el cuadro neurológico. A todo eso se sumaba la rinitis crónica que arrastraba desde hacía meses.`,`Durante la internación su estado llegó a ser muy delicado. Continuaba con signos neurológicos y comenzó un tratamiento descompresivo. También necesitó una sonda para poder alimentarse e hidratarse. A pesar del cuadro, empezó a mostrar pequeños avances: logró incorporarse, sentarse y, después de iniciar el tratamiento, pudo orinar. Lu y Fran, quienes la acompañaban durante esta etapa, llegaron a preparar un espacio de aislamiento en su casa para que pudiera continuar allí el tratamiento si recibía el alta.`,`Entre el 27 y el 29 de julio aparecieron señales que dieron esperanza. Maxine respondía al tratamiento, podía mantenerse en pie por sus propios medios y, aunque todavía se tambaleaba y se caía por los signos neurológicos, intentaba volver a levantarse y recuperar pequeñas rutinas, como acercarse a las piedritas.`,`La evolución no fue lineal. El 31 de julio volvió a presentar algo de fiebre, decaimiento y un aumento leve de los signos neurológicos, por lo que tuvo que ser medicada y controlada nuevamente. El 2 de agosto llegó otra pequeña buena noticia: pese a seguir teniendo una sonda conectada al esófago y ser alimentada por ella cada tres horas, Maxine había comenzado a comer por su cuenta.`,`El 3 de agosto volvió a ser internada. Ese día estaba decaída y, mientras la auscultaban, sufrió una convulsión breve, suficiente para que quedara nuevamente bajo cuidado veterinario. Al día siguiente fue evaluada por una neuróloga y se informó que presentaba lesiones a nivel cerebral. Su pronóstico ya no era bueno y quienes la acompañaban comenzaron a priorizar que atravesara ese momento sin dolor.`,`El 5 de agosto llegó la despedida. Después de meses de tratamientos, estudios, internaciones, recaídas y pequeños avances, Maxine falleció. Según la publicación con la que fue despedida, se fue mientras dormía, sin sufrir y acompañada hasta el final por las personas que habían decidido no dejarla sola.`,`No fue posible cambiar el desenlace de su enfermedad, pero sí cambió por completo la historia con la que Maxine llegó hasta él. Después de años sobreviviendo en la calle, pasó sus últimos meses con una familia que la cuidó, personas que la acompañaron en cada control y un equipo veterinario que continuó intentando ayudarla incluso en los momentos más difíciles. Maxine no se fue sola ni olvidada: se fue después de haber conocido un hogar y de haber sido profundamente querida.`],currentNeeds:[],updates:[{date:`2026-08-05`,title:`Hasta siempre, Maxine`,paragraphs:[`El 5 de agosto llegó la noticia que nadie quería recibir: Maxine falleció después de meses de tratamiento y de una última etapa especialmente delicada.`,`La publicación con la que fue despedida contó que se fue mientras dormía, sin sufrir y después de haber recibido todo el acompañamiento posible durante sus últimos días.`,`Su historia había comenzado con años de vida en la calle y continuó con un rescate, una familia que la recibió, tratamientos, internaciones y un equipo veterinario que no dejó de intentar ayudarla.`,`Aunque no fue posible cambiar el desenlace, Maxine ya no era una gata sola, enferma y olvidada. Sus últimos meses estuvieron rodeados de cuidados y de personas que la acompañaron hasta el final.`]},{date:`2026-08-04`,title:`Su pronóstico volvió a ser muy delicado`,paragraphs:[`Maxine continuaba internada y fue evaluada por una neuróloga. En esa consulta se informó que presentaba lesiones a nivel cerebral y que su pronóstico no era bueno.`,`Después de todo lo que había atravesado, quienes la acompañaban explicaron que la prioridad era seguir a su lado sin permitir que sufriera.`,`La publicación recordó que habían pasado aproximadamente cuatro meses desde su rescate y reafirmó la promesa de acompañarla más allá de cualquier posibilidad de adopción.`]},{date:`2026-08-03`,title:`Maxine tuvo que ser internada nuevamente`,paragraphs:[`Después de algunos días con avances y retrocesos, Maxine volvió a mostrar decaimiento y tuvo que ser internada nuevamente.`,`Mientras la auscultaban sufrió una convulsión leve y breve, pero suficiente para que quedara bajo el cuidado de los profesionales.`,`La recaída volvió a mostrar que su evolución no era lineal y que todavía necesitaba seguimiento veterinario permanente.`]},{date:`2026-08-02`,title:`Empezó a comer por su cuenta`,paragraphs:[`Después de un día previo con fiebre y aumento de los signos neurológicos, Maxine dio un paso muy importante: comenzó a comer por su cuenta.`,`Todavía tenía una sonda conectada directamente al esófago y Lu y Fran continuaban alimentándola por allí cada tres horas, pero el hecho de que volviera a comer sola fue recibido como una señal muy alentadora.`,`Además de pollo, estaba comiendo alimento húmedo nutritivo mientras continuaba con el tratamiento y los controles.`]},{date:`2026-07-31`,title:`Un nuevo día difícil`,paragraphs:[`Maxine presentó un poco de fiebre, decaimiento y un leve aumento de los signos neurológicos, por lo que se adelantó su visita a la veterinaria.`,`Fue medicada y quedó con un nuevo control previsto para el día siguiente.`,`La actualización reflejó nuevamente que su recuperación tenía días mejores y otros más difíciles, y que cada cambio requería seguimiento cercano.`]},{date:`2026-07-29`,title:`Su progreso seguía siendo notable`,paragraphs:[`Maxine continuaba mejorando día a día. Aunque todavía presentaba signos neurológicos, la publicación describía un progreso visible en comparación con los días anteriores.`,`Seguía mostrando ganas de moverse, responder y continuar con el tratamiento mientras permanecía acompañada por su familia de tránsito.`]},{date:`2026-07-28`,title:`Volvía a levantarse e intentarlo`,paragraphs:[`Maxine ya intentaba acercarse nuevamente a las piedritas y realizar algunas de sus rutinas por sí misma.`,`Los signos neurológicos todavía hacían que se tambaleara y se cayera, pero volvía a levantarse e intentaba continuar.`,`La evolución seguía siendo delicada, aunque esos pequeños avances mostraban una respuesta al tratamiento.`]},{date:`2026-07-27`,title:`Empezó a responder al tratamiento`,paragraphs:[`La actualización de ese día trajo noticias alentadoras: Maxine estaba respondiendo al tratamiento y, aunque todavía presentaba signos neurológicos, ya podía mantenerse en pie por sus propios medios.`,`Durante esos días también habían llegado resultados que completaban un cuadro complejo: además de la rinitis crónica, VILEF y micoplasma, Maxine dio positiva a toxoplasmosis, uno de los resultados utilizados para explicar los síntomas neurológicos.`,`Necesitó una sonda para alimentarse e hidratarse y recibió un tratamiento intensivo. A pesar de la gravedad de su estado, había logrado sentarse e incorporarse.`,`La rescatista informó que había podido entregar $120.000 en la veterinaria y que el saldo veterinario general continuaba siendo de $1.379.206,84. Ese monto correspondía a la deuda acumulada de los rescates, no a una deuda individual de Maxine.`]},{date:`2026-07-24`,title:`Llegaron los primeros diagnósticos`,paragraphs:[`Los estudios permitieron empezar a ponerle nombre al complejo cuadro que atravesaba Maxine. Se informó que había dado positiva a VILEF —leucemia felina— y a micoplasma.`,`Según la actualización, el micoplasma había provocado una anemia muy importante y ayudaba a explicar parte de los problemas que venía atravesando.`,`Maxine continuaba con síntomas neurológicos y su estado seguía siendo delicado, aunque después de comenzar un tratamiento descompresivo había mostrado algunas pequeñas señales favorables.`,`En esos días la deuda veterinaria general rondaba $1.500.000 y todavía faltaban estudios para completar el diagnóstico.`]},{date:`2026-07-23`,title:`Fiebre, síntomas neurológicos e internación`,paragraphs:[`Maxine había sido rescatada meses antes junto a sus tres bebés y, aunque había mejorado de su cuadro inicial, la mucosidad respiratoria nunca había desaparecido por completo.`,`Dos días antes de esta publicación comenzó con fiebre y fue llevada a la veterinaria, donde recibió medicación.`,`Con el correr de las horas aparecieron síntomas neurológicos y Maxine quedó internada mientras le realizaban numerosos estudios.`,`En ese momento se había descartado un ACV, pero todavía se esperaba el resto de los resultados para saber a qué se estaban enfrentando.`,`La deuda veterinaria general se encontraba nuevamente alrededor de $1.500.000 y aún quedaban estudios por realizar.`]},{date:`2026-05-02`,title:`Una recuperación lenta pero con buen apetito`,paragraphs:[`Maxine continuaba mejorando muy lentamente y todavía necesitaba varias semanas de tratamiento con doxiciclina.`,`A pesar de eso, tenía buen apetito y recibía una alimentación nutritiva para acompañar su recuperación.`,`Si todo evolucionaba bien, una vez finalizado el tratamiento estaba previsto avanzar con su castración.`]},{date:`2026-04-30`,title:`Una ecografía descartó una nueva preñez`,paragraphs:[`Durante esa semana le realizaron una ecografía porque su abdomen se veía distendido y se había considerado la posibilidad de una nueva preñez.`,`El estudio descartó esa sospecha. La distensión estaba relacionada con la cantidad de alimento que estaba comiendo.`,`Después de años buscando qué comer, Maxine devoraba el alimento con entusiasmo. La indicación veterinaria fue mantener la cantidad diaria, pero dividirla en más porciones para facilitar su digestión.`]},{date:`2026-04-15`,title:`Micoplasma positivo y tratamiento por 30 días`,paragraphs:[`Los estudios de PCR dieron negativos para VIF y VILEF, una muy buena noticia dentro del cuadro que venía atravesando Maxine.`,`Sin embargo, dio positiva a micoplasma y se indicó un tratamiento de aproximadamente 30 días.`,`Aunque todavía continuaba con mucosidad, la publicación señalaba que ese diagnóstico permitía avanzar con un tratamiento concreto.`,`Sus bebés ya habían comenzado a comer y se preparaban para ir con sus familias, lo que permitiría concentrar todos los cuidados en Maxine.`]},{date:`2026-04-13`,title:`Necesitaba estudios para encontrar un diagnóstico`,paragraphs:[`El cuadro respiratorio de Maxine seguía sin mejorar a pesar de los antibióticos y continuaba expulsando mucosidad, incluso con sangre.`,`Se necesitaban más estudios para intentar llegar a un diagnóstico más certero. El costo estimado informado para esos estudios era de aproximadamente $200.000.`,`En paralelo, la deuda veterinaria general acumulada había llegado a $783.203, un monto que correspondía al conjunto de los rescates y no exclusivamente a Maxine.`]},{date:`2026-04-12`,title:`El cuadro respiratorio seguía sin mejorar`,paragraphs:[`A pesar de estar medicada con antibióticos, Maxine continuaba con abundante mucosidad y episodios en los que aparecía sangre.`,`Los veterinarios indicaron realizar estudios más profundos, entre ellos un lavaje nasal y una laringoscopia bajo anestesia, además de hemogramas y PCR para evaluar VIF y VILEF.`,`En ese momento todavía estaba criando a sus bebés, por lo que también se estaba estimulando a los pequeños para que comenzaran a comer por su cuenta y así poder concentrar más cuidados en ella.`]},{date:`2026-04-07`,title:`Un nuevo episodio respiratorio`,paragraphs:[`Después de un control de sus bebés, Maxine sufrió un nuevo episodio respiratorio y tuvo que regresar a la veterinaria.`,`Le realizaron placas y todavía se observaba mucha mucosidad, por lo que volvió a ser medicada y quedó con un nuevo control programado.`,`En esa publicación se informó que la deuda veterinaria general se mantenía por encima de los $600.000 debido a los controles, estudios y medicación de los distintos casos.`]},{date:`2026-04-06`,title:`Controles para Maxine y sus bebés`,paragraphs:[`Maxine y sus bebés continuaban bajo seguimiento veterinario. Dos de los pequeños ya no necesitaban la cinta correctiva, mientras que uno debía continuar algunos días más para corregir su postura.`,`Maxine iba mejorando de a poco, aunque todavía seguía con mucha mucosidad y necesitaba controles.`,`Ese día se informó que una de las cuentas veterinarias había sido cancelada, aunque todavía quedaba un saldo general cercano a $700.000 en Clínica San Lorenzo.`]},{date:`2026-03-28`,title:`Comenzó el tratamiento de sus complicaciones respiratorias`,paragraphs:[`Maxine ya se encontraba en un tránsito, relajada y acompañada, mientras continuaba criando a sus bebés.`,`El día anterior había comenzado un tratamiento para combatir sus complicaciones respiratorias.`,`Los pequeños también mostraban avances y ya no tenían los ojos pegados, una señal de mejoría después de los primeros cuidados.`,`Todavía no estaban en adopción y la prioridad era continuar estabilizando a toda la familia.`]}],updatedAt:`2026-08-05`,seoDescription:`Conocé la historia de Maxine, rescatada junto a sus tres bebés y acompañada durante meses de tratamientos hasta sus últimos días. Hoy la recordamos en memoria.`},{slug:`fenix`,name:`Fénix`,statuses:[`recovering`,`closed`],featured:!1,summary:`Fénix fue encontrado en estado crítico, con una fractura expuesta y una grave miasis en una de sus patas. Después de semanas de estabilización, controles y una cirugía de amputación, logró recuperarse y adaptarse a su nueva vida. Hoy está adoptado y vive rodeado del cariño de la familia que primero lo recibió en tránsito.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448210/WhatsApp_Image_2026-08-22_at_20.37.59_2.jpg`,width:1600,height:900,alt:`Fénix recuperado y disfrutando de su nueva vida en familia`,objectPosition:`50% 40%`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448205/WhatsApp_Image_2026-08-22_at_19.26.17.jpg`,width:900,height:1600,alt:`Fénix durante los primeros días de recuperación después de su rescate`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448205/WhatsApp_Image_2026-08-22_at_19.26.17_1.jpg`,width:900,height:1600,alt:`Fénix descansando en su hogar de tránsito mientras recuperaba fuerzas`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448207/WhatsApp_Image_2026-08-22_at_20.35.39.jpg`,width:900,height:1600,alt:`Fénix durante uno de sus controles veterinarios`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448206/WhatsApp_Image_2026-08-22_at_20.35.39_1.jpg`,width:900,height:1600,alt:`Fénix después de la cirugía de amputación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448209/WhatsApp_Image_2026-08-22_at_20.37.35.jpg`,width:900,height:1600,alt:`Fénix adaptado a moverse con tres patas en su hogar definitivo`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448211/WhatsApp_Image_2026-08-22_at_20.37.59.jpg`,width:900,height:1600,alt:`Fénix adaptado a moverse con tres patas en su hogar definitivo`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448208/WhatsApp_Image_2026-08-22_at_20.37.59_1.jpg`,width:900,height:1600,alt:`Fénix adaptado a moverse con tres patas en su hogar definitivo`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448212/WhatsApp_Image_2026-08-22_at_20.38.14.jpg`,width:900,height:1600,alt:`Fénix adaptado a moverse con tres patas en su hogar definitivo`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448213/WhatsApp_Image_2026-08-22_at_20.39.47.jpg`,width:900,height:1600,alt:`Fénix adaptado a moverse con tres patas en su hogar definitivo`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787448214/WhatsApp_Image_2026-08-22_at_20.39.48.jpg`,width:900,height:1600,alt:`Fénix adaptado a moverse con tres patas en su hogar definitivo`}],story:[`Fénix, a quien en las publicaciones originales también llamaron Feli, Felipe y Gatoman, tenía aproximadamente cuatro años cuando fue encontrado en un galpón después de haber pasado varios días en un estado muy delicado. Tenía una fractura expuesta y una miasis severa que había comprometido por completo una de sus patas. Una persona llamada Verónica lo vio, pidió ayuda y así comenzó su rescate.`,`Ingresó de urgencia a Clínica San Lorenzo la noche del 30 de enero de 2026. Costó mucho estabilizarlo y durante esas primeras horas existía el temor de que no lograra pasar la noche. Debido a su estado y a lo bajos que estaban sus glóbulos rojos, llegó a buscarse con urgencia un gato donante para una posible transfusión.`,`Fénix logró superar esa primera noche. Al día siguiente amaneció con apetito y comenzó, muy lentamente, a recuperar fuerzas. La transfusión finalmente no se realizó en ese momento porque su evolución empezaba a mostrar señales favorables. Sin embargo, la pata estaba demasiado dañada y los veterinarios ya habían determinado que sería necesario amputarla una vez que estuviera lo suficientemente fuerte para soportar la cirugía.`,`Durante los primeros días de febrero continuó internado, con curaciones, medicación y cambios de vendaje. Clínicamente mejoraba y comía con muchas ganas, pero todavía necesitaba un lugar tranquilo donde recuperarse antes de la operación. Después de una búsqueda urgente apareció ese tránsito: Lu y su familia lo recibieron y le dieron un espacio seguro donde descansar, moverse lo menos posible y continuar con todos los cuidados indicados.`,`El 7 de febrero llegaron resultados que trajeron alivio: los estudios dieron negativos para micoplasma, VIF y VILEF. En los controles lo encontraron bien, continuaron las curaciones y los cambios de vendaje, y recibió un tónico para ayudarlo a fortalecerse.`,`La recuperación previa a la cirugía tomó más tiempo de lo esperado. Sus glóbulos rojos seguían bajos: en una actualización del 18 de febrero se informó que habían pasado aproximadamente de un 10 % en los primeros días a un 21 %. La evolución era lenta pero favorable, y por seguridad la cirugía se postergó mientras continuaba recuperando hematocrito y fuerzas.`,`Durante esas semanas Fénix fue cambiando por completo. En el tránsito estaba más relajado, había aumentado de peso, comenzó a socializar con los otros gatos de la casa y aprendió a sentirse seguro. Lo que en un principio había sido solamente un lugar temporal empezó a convertirse en algo mucho más importante.`,`Finalmente, cuando estuvo en condiciones de enfrentarla, se realizó la cirugía de amputación. La intervención fue exitosa y, ese mismo día, pudo regresar a la casa donde venía recuperándose. La amputación no significó el final de su historia sino el comienzo de una vida con mayor bienestar y sin una pata que ya no podía recuperarse.`,`Junto con la noticia de la cirugía llegó otra que terminó de cambiar su destino: Fénix ya tenía una familia para siempre. Lu y su familia, que lo habían recibido cuando necesitaba un tránsito para recuperarse, decidieron adoptarlo. La adopción se definió incluso antes de completar todos sus controles, después de haberlo acompañado durante los momentos más difíciles.`,`Con el tiempo se acostumbró a movilizarse con tres patas y a convivir con los demás animales de la casa. Para el 22 de marzo las publicaciones ya mostraban a un Fénix completamente integrado a su nueva vida: acompañado, enamorado de otra gata de la familia y compartiendo una rutina que parecía imposible cuando había llegado a la veterinaria en enero.`,`Su historia pasó de una noche en la que apenas se esperaba que sobreviviera a una recuperación, una cirugía exitosa y una adopción definitiva. Fénix encontró mucho más que tratamiento veterinario: encontró un hogar en el mismo lugar que primero había abierto sus puertas para ayudarlo a recuperarse.`],currentNeeds:[],updates:[{date:`2026-03-22`,title:`Una nueva vida en familia`,paragraphs:[`Fénix ya estaba completamente integrado a su hogar definitivo. Las publicaciones lo mostraban adaptado a su nueva vida, conviviendo con los otros gatos de la familia y disfrutando del vínculo que había construido con ellos.`,`Después del rescate, el tránsito, la recuperación y la amputación, su historia había llegado a un final feliz: estaba adoptado y rodeado del cariño de la misma familia que lo había recibido cuando todavía necesitaba recuperar fuerzas para poder ser operado.`]},{date:`2026-02-24`,title:`Cada vez más fuerte antes de la cirugía`,paragraphs:[`Fénix continuaba recuperándose y su cambio era cada vez más visible. Estaba más relajado, había aumentado de peso y jugaba con los otros gatos de la casa.`,`La cirugía todavía no se había realizado porque necesitaba seguir recuperando hematocrito. Los controles, la medicación y los cambios de vendaje continuaban mientras los veterinarios esperaban que estuviera en mejores condiciones para afrontar la amputación.`,`En esos días se informó que la deuda veterinaria general había vuelto a aumentar con los controles y los gastos de los distintos casos. Ese saldo no correspondía exclusivamente a Fénix.`]},{date:`2026-02-18`,title:`La cirugía se postergó para darle más tiempo`,paragraphs:[`Aunque Fénix evolucionaba muy bien, sus glóbulos rojos continuaban bajos. Según la actualización, habían pasado aproximadamente de un 10 % al comienzo a un 21 %.`,`El avance era lento pero favorable y, como la cirugía todavía implicaba un riesgo, se decidió postergarla hasta la semana siguiente para darle más tiempo de recuperación.`,`Ese día se habían realizado nuevas entregas de dinero en la veterinaria y se informó un saldo general de $390.974, al que todavía debían sumarse la cirugía y los gastos posteriores. Se trataba del saldo veterinario general informado por la rescatista.`]},{date:`2026-02-07`,title:`Buenas noticias en sus estudios`,paragraphs:[`Los resultados de laboratorio de Fénix dieron negativos para micoplasma, VIF y VILEF, una muy buena noticia considerando el estado en el que había llegado.`,`En el control lo encontraron clínicamente muy bien. Se realizó una nueva curación, se cambió el vendaje y recibió un tónico para ayudarlo a recuperar fuerzas antes de la cirugía.`,`Ese día se informó una entrega de $116.000 en la veterinaria y un saldo general restante de $444.724. Ese monto correspondía a la cuenta veterinaria acumulada, no a una deuda individual de Fénix.`]},{date:`2026-02-04`,title:`Consiguió un tránsito para recuperarse`,paragraphs:[`Fénix estaba evolucionando favorablemente y necesitaba un lugar tranquilo donde recuperar fuerzas antes de la cirugía de amputación.`,`Después de una búsqueda urgente consiguió tránsito. Lu y su familia lo recibieron y le dieron un espacio seguro donde descansar, recibir su medicación y limitar la movilidad de la pata afectada.`,`En esos días la rescatista informaba una deuda veterinaria general cercana a los $600.000 mientras seguían sumándose controles y tratamientos de los distintos casos.`]},{date:`2026-02-02`,title:`Empezó a recuperarse y buscaba tránsito`,paragraphs:[`Fénix mostraba una evolución clínica muy buena y tenía un apetito voraz, una señal alentadora después del estado crítico con el que había ingresado.`,`Se informó un pago de $66.300 y un saldo veterinario general de $520.396, al que todavía debían sumarse los controles y la futura cirugía de amputación.`,`Además de continuar estabilizándolo, la prioridad era conseguir un tránsito donde pudiera descansar, recuperar fuerzas y llegar en mejores condiciones a la operación.`]},{date:`2026-01-31`,title:`Logró pasar la primera noche`,paragraphs:[`Fénix había ingresado la noche anterior, el 30 de enero, con una fractura expuesta y una miasis severa que llevaba varios días de evolución. Tenía aproximadamente cuatro años y su estado era muy delicado.`,`Costó mucho estabilizarlo y durante las primeras horas el objetivo era simplemente que lograra pasar la noche. Fénix lo consiguió y al día siguiente amaneció con apetito, olfateando el alimento y comiendo a pesar del dolor.`,`Debido a su estado se había buscado con urgencia un gato donante para una posible transfusión, aunque finalmente se decidió no realizarla en ese momento porque poco a poco comenzó a recuperar fuerzas.`,`La pata afectada ya estaba demasiado comprometida y la amputación sería necesaria una vez que pudiera estabilizarse y llegar en mejores condiciones a la cirugía.`,`Cuando ingresó, la rescatista ya mantenía una deuda previa de aproximadamente $170.000 en Clínica San Lorenzo, a la que comenzarían a sumarse los gastos de Fénix. Ese monto era parte de la deuda veterinaria general.`]}],updatedAt:`2026-03-22`,seoDescription:`Conocé la historia de Fénix, rescatado con una fractura expuesta y una grave miasis, su recuperación después de una amputación y el hogar definitivo que encontró junto a su familia.`},{slug:`pochoclo`,name:`Pochoclo`,statuses:[`memorial`],featured:!1,summary:`Pochoclo fue rescatado después de caer desde un árbol a un patio y no poder volver a subir. Su cuerpo mostraba años de vida en la calle y, durante los estudios, aparecieron problemas neurológicos, renales, anemia y ViLeF. A pesar de todos los cuidados, su cuadro se agravó rápidamente y falleció pocos días después del rescate, acompañado y querido hasta el final.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787497141/WhatsApp_Image_2026-08-23_at_11.33.46_1.jpg`,width:1600,height:900,alt:`Pochoclo durante los días en que recibió cuidados después de su rescate`,objectPosition:`50% 40%`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787497141/WhatsApp_Image_2026-08-23_at_11.33.46.jpg`,width:900,height:1600,alt:`Pochoclo durante su internación en Clínica San Lorenzo`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787497141/WhatsApp_Image_2026-08-23_at_11.33.47.jpg`,width:900,height:1600,alt:`Pochoclo después de ser higienizado y atendido por el equipo veterinario`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787497141/WhatsApp_Image_2026-08-23_at_11.33.47_1.jpg`,width:900,height:1600,alt:`Pochoclo durante su recuperación y seguimiento veterinario`}],story:[`La historia de Pochoclo comenzó el 14 de julio de 2026 con un aviso de urgencia. Había caído desde un árbol al patio de una casa y no había podido volver a subir. Cuando fueron a buscarlo, era evidente que llevaba mucho tiempo sobreviviendo en la calle: no estaba castrado, le faltaban varias piezas dentales, tenía el pelo completamente apelmazado y no presentaba sensibilidad en la cola.`,`Fue trasladado de inmediato a Clínica San Lorenzo, donde quedó internado. Al día siguiente lo anestesiaron para poder retirar la gran cantidad de pelo apelmazado que cubría su cuerpo y evaluar mejor su estado. Le realizaron placas y estudios, permaneció con suero porque su orina era muy oscura y comenzó tratamiento con doxiciclina debido a una anemia importante.`,`Dentro de un cuadro todavía incierto había pequeñas señales alentadoras: Pochoclo tenía mucho apetito y se consiguió un tránsito para cuando pudiera dejar la internación. Durante esos días también se intentaba entender el origen de sus dificultades de movilidad y de la falta de sensibilidad que presentaba.`,`Pochoclo llegó a recibir el alta, aunque todavía necesitaba una sonda urinaria y en las últimas horas había disminuido la movilidad de sus miembros traseros. Las imágenes mostraban una lesión antigua en la columna y los profesionales debían determinar cuánto podía estar relacionada con su imposibilidad de hacer sus necesidades por sí mismo. También se indicó una consulta cardiológica.`,`Después de haber vivido toda su vida en la calle, permanecer encerrado dentro de un departamento le generaba episodios importantes de estrés. Por eso su tránsito acondicionó un patio para que pudiera estar cómodo, tomar aire y disfrutar algunos ratos de sol sin dejar de recibir alimentación, medicación y todos los cuidados necesarios.`,`Durante el fin de semana su estado volvió a complicarse. Dejó de comer, comenzó a orinar con sangre y la sonda se obstruyó con pequeños coágulos. En la veterinaria retiraron la sonda y vaciaron manualmente una vejiga que estaba muy llena. Se intentó comprobar si podía volver a orinar por sus propios medios, pero no ocurrió.`,`Al regresar a control encontraron nuevamente mucha orina acumulada en su vejiga y también materia fecal retenida en los intestinos. El cuadro era mucho más complejo de lo que parecía al comienzo: Pochoclo dio positivo a ViLeF, tenía los riñones muy comprometidos, continuaba anémico y existían además posibles problemas cardiológicos.`,`Los profesionales determinaron que presentaba una vejiga neurogénica y que ya no podía orinar ni defecar por sus propios medios. Su cuerpo estaba muy deteriorado y la posibilidad de ofrecerle una vida sin sufrimiento se volvía cada vez más difícil. Las siguientes horas eran cruciales.`,`Ese mismo 20 de julio, luego de una nueva descompensación y otra internación, llegó el momento de despedirlo. La decisión estuvo atravesada por algo que había acompañado todo el rescate: no prolongar su dolor cuando ya no existía una recuperación que pudiera devolverle calidad de vida.`,`Pochoclo estuvo apenas unos días bajo cuidado, pero en ese tiempo conoció algo que probablemente le había faltado durante años de calle: personas pendientes de él, alimento, un lugar preparado para que pudiera sentirse tranquilo, atención veterinaria y mucho afecto. No pudo tener la vida larga y cómoda que todos hubieran querido para él, pero no se fue solo.`,`Su historia quedó como recuerdo de esos rescates en los que llegar, intentar y acompañar también importa, incluso cuando no es posible cambiar el desenlace. Durante sus últimos días hubo muchas personas intentando darle una oportunidad y asegurándose de que, hasta el final, estuviera cuidado y rodeado de cariño.`],currentNeeds:[],updates:[{date:`2026-07-20`,title:`Hasta siempre, Pochoclo`,paragraphs:[`Ese día se confirmó la noticia más triste: Pochoclo había fallecido después de varios días de lucha y cuidados intensivos.`,`Su cuadro se había vuelto irreversible y el objetivo pasó a ser evitar que continuara sufriendo. En la despedida se recordó que, aunque había pasado prácticamente toda su vida en la calle, durante sus últimos cuatro días estuvo acompañado, atendido y rodeado de cariño.`,`Pochoclo no tuvo el final que todos esperaban, pero su huella quedó en cada una de las personas que lo rescataron, lo cuidaron y estuvieron pendientes de él hasta el último momento.`]},{date:`2026-07-20`,title:`Un cuadro muy delicado`,paragraphs:[`Durante el fin de semana Pochoclo dejó de comer, comenzó a orinar con sangre y su sonda se tapó con pequeños coágulos. En la veterinaria retiraron la sonda y vaciaron manualmente una vejiga que estaba muy llena.`,`Se intentó dejarlo sin sonda para comprobar si podía orinar por sí mismo, pero no pudo hacerlo. En el control siguiente su vejiga volvía a tener mucha orina acumulada y sus intestinos estaban llenos de materia fecal.`,`Además, se confirmó que Pochoclo era positivo a ViLeF. Tenía los riñones muy comprometidos, continuaba con anemia y existían posibles problemas cardiológicos.`,`Los profesionales determinaron que presentaba una vejiga neurogénica y que no podía orinar ni defecar por sus propios medios. El pronóstico era muy delicado y las siguientes 48 horas se consideraban cruciales.`,`La deuda veterinaria general informada en esa actualización era de $810.282. Ese monto correspondía a la cuenta acumulada de los casos atendidos y no exclusivamente a Pochoclo.`]},{date:`2026-07-15`,title:`Estudios, tratamiento y un tránsito para Pochoclo`,paragraphs:[`Después del rescate comenzaron a retirar todo el pelo apelmazado que cubría su cuerpo. Era evidente que Pochoclo llevaba mucho tiempo sin recibir cuidados.`,`Le realizaron placas y estudios. Permanecía con suero porque su orina era muy oscura y comenzó tratamiento con doxiciclina debido a una anemia importante.`,`Las siguientes 24 a 48 horas eran importantes para poder comprender mejor su cuadro. Dentro de toda la incertidumbre, Pochoclo mantenía un muy buen apetito.`,`Ese día también llegó una noticia importante: se había conseguido tránsito para continuar sus cuidados cuando pudiera salir de la veterinaria.`,`En una actualización posterior se informó que llegó a recibir el alta con sonda y con menor movilidad en los miembros traseros. Las imágenes mostraban una lesión vieja en la columna y se indicó continuar estudiando su relación con las dificultades para hacer sus necesidades por sí mismo.`,`También se había indicado una consulta cardiológica cuyo costo informado era de $80.000. En esos días se realizó una entrega de $400.000 en la veterinaria, aunque todavía no se conocía el saldo general pendiente.`]},{date:`2026-07-14`,title:`Rescate de última hora`,paragraphs:[`Pasadas las 20:30 llegó el aviso de un gato que había caído desde un árbol a un patio y no había podido volver a subir. Fueron a buscarlo y lo trasladaron inmediatamente a Clínica San Lorenzo.`,`No se sabía con certeza su edad. Su estado reflejaba una vida muy dura en la calle: no estaba castrado, le faltaban varias piezas dentales, tenía muchísimo pelo apelmazado y no presentaba sensibilidad en la cola.`,`Quedó internado para ser estabilizado y estudiado. La intención era anestesiarlo al día siguiente para retirar el pelo apelmazado y poder revisar si existían otras lesiones.`,`Desde el primer momento se plantearon dos necesidades: conseguir un tránsito para cuando tuviera el alta y reunir ayuda para afrontar los gastos veterinarios que comenzaban a sumarse.`]}],updatedAt:`2026-07-20`,seoDescription:`Conocé la historia de Pochoclo, un gato rescatado después de años en la calle que recibió atención veterinaria y acompañamiento hasta sus últimos días.`},{slug:`patan`,name:`Patán`,statuses:[`recovering`,`closed`],featured:!0,summary:`Patán es un galgo de aproximadamente 4 años que sobrevivió durante años en la calle. Fue rescatado con una fractura expuesta e infectada después de pasar varios días refugiado debajo de unas chapas. Tras semanas de cuidados y una cirugía de amputación, logró recuperarse y empezar una vida completamente nueva.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505883/WhatsApp_Image_2026-08-23_at_12.23.00_2.jpg`,width:1600,height:900,alt:`Patán durante su recuperación`,objectPosition:`50% 40%`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.57.jpg`,width:900,height:1600,alt:`Patán al comienzo de su rescate`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505880/WhatsApp_Image_2026-08-23_at_12.22.57_1.jpg`,width:900,height:1600,alt:`Patán durante sus primeros controles veterinarios`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.57_2.jpg`,width:900,height:1600,alt:`Patán con su pata vendada durante el tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.57_3.jpg`,width:900,height:1600,alt:`Patán después de su cirugía de amputación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.57_4.jpg`,width:900,height:1600,alt:`Patán recuperándose después de la cirugía`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.58.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.58_1.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505882/WhatsApp_Image_2026-08-23_at_12.22.59.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.59_1.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505881/WhatsApp_Image_2026-08-23_at_12.22.59_2.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505882/WhatsApp_Image_2026-08-23_at_12.22.59_3.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505882/WhatsApp_Image_2026-08-23_at_12.22.59_4.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505880/WhatsApp_Image_2026-08-23_at_12.23.00.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787505883/WhatsApp_Image_2026-08-23_at_12.23.00_1.jpg`,width:900,height:1600,alt:`Patán disfrutando de su nueva vida durante la recuperación`}],story:[`Patán es un galgo de aproximadamente 4 años. Durante prácticamente toda su vida conoció la calle, el frío, el hambre y la necesidad de sobrevivir con lo que pudiera encontrar.`,`A comienzos de mayo de 2026 una vecina pidió ayuda por él. Había sido mordido por otro perro y llevaba varios días refugiado debajo de unas chapas en el barrio La Unión. La mujer que lo encontró intentaba alimentarlo y darle antibióticos, pero la lesión continuó empeorando hasta dejar parte del hueso completamente expuesto.`,`Cuando finalmente pudieron rescatarlo, el cuadro era mucho más complejo de lo que se veía a simple vista. Patán tenía una fractura expuesta con infección que alcanzaba el hueso, lesiones anteriores, una fractura vieja mal consolidada, piezas dentales dañadas y balines o perdigones alojados debajo de la piel.`,`Aun después de haber pasado por todo eso, seguía moviendo la cola cuando recibía una caricia. Después de años sobreviviendo y desconfiando del mundo, Patán comenzó a descubrir que no todas las manos lastiman.`,`Uno de los primeros grandes desafíos fue conseguirle un tránsito. Una vez encontrado, pudo dormir por primera vez dentro de una casa, sobre un sillón, con comida todos los días y personas pendientes de su recuperación. Para un perro que había pasado su vida durmiendo bajo chapas, ese simple momento marcó el comienzo de otra vida.`,`Los primeros días estuvieron llenos de controles veterinarios. Necesitó suero por deshidratación, antibióticos, curaciones, cambios de vendaje y una alimentación especial mientras recuperaba fuerzas. También comenzaron los análisis y estudios necesarios para determinar cuándo estaría en condiciones de ser operado.`,`Durante los estudios apareció además una pequeña masa que debía continuar evaluándose. Se realizaron análisis de sangre, ecografía y placas antes de poder avanzar con la cirugía.`,`Los profesionales determinaron que la pata lesionada ya no podía salvarse. La infección, la fractura expuesta y el tiempo transcurrido sin atención hacían necesaria la amputación para darle una verdadera oportunidad de vida.`,`El 18 de mayo llegó finalmente el día de la cirugía. Se amputó el miembro inferior izquierdo, se retiró uno de los balines que tenía alojados en el cuerpo, se extrajo la masa encontrada durante los controles y también fue castrado. La muestra extraída fue enviada a analizar. En las publicaciones aportadas no se informa posteriormente el resultado de ese estudio.`,`La cirugía salió bien. Apenas unas horas después Patán ya estaba comiendo y comenzando el camino de recuperación. Después de una vida sobreviviendo en la calle, ese día fue presentado como su nuevo comienzo.`,`Los días siguientes mostraron un cambio enorme. Volvió a comer con ganas, empezó a relacionarse con otros animales de la casa, buscaba cariño, movía la cola y cada vez estaba más cómodo con su nueva realidad.`,`El 28 de mayo ya había atravesado la parte más difícil del proceso. Seguía recuperándose de la cirugía, pero estaba muchísimo mejor y comenzaba a disfrutar de las pequeñas cosas que antes nunca había tenido: una cama, compañía, alimento, caricias y personas preocupadas por él.`,`Finalmente, el 1 de junio tuvo su último control. Le retiraron los puntos, la herida estaba completamente cicatrizada y pudo despedirse del collar isabelino. Incluso durante el procedimiento estaba tan tranquilo que se quedó dormido.`,`Patán pasó de esconderse herido debajo de unas chapas a dormir bajo techo y rodeado de cuidados. Perdió una pata, pero ganó algo que hasta ese momento prácticamente no había conocido: la posibilidad de dejar de sobrevivir y empezar a vivir.`],currentNeeds:[],updates:[{date:`2026-06-01`,title:`Último control y una herida completamente cicatrizada`,paragraphs:[`Patán tuvo su último control veterinario después de la cirugía.`,`Le retiraron los puntos y los profesionales encontraron la herida en excelentes condiciones, completamente cicatrizada.`,`También pudo dejar definitivamente el collar isabelino que había utilizado durante buena parte de su recuperación.`,`La tranquilidad de Patán durante el procedimiento fue tal que, mientras le retiraban los puntos, se quedó dormido.`,`La publicación marcó el cierre de la etapa médica más difícil de su historia y el comienzo definitivo de su nueva vida.`,`En esa actualización se informó una deuda veterinaria general de $1.320.208.`]},{date:`2026-05-28`,title:`Patán ya había pasado por lo más difícil`,paragraphs:[`Después del abandono, la fractura, la infección y una cirugía enorme, Patán se encontraba muchísimo mejor.`,`Comía, movía la cola, pedía mimos y empezaba a mostrar cada vez más su personalidad.`,`También comenzó a compartir espacios con los demás animales de la casa. En una de las publicaciones aparece junto a su compañera María Macanas, con quien ya comenzaba a convivir.`,`Para ese momento la deuda veterinaria general todavía superaba el millón de pesos, por lo que continuaban solicitándose colaboraciones y difusión.`]},{date:`2026-05-23`,title:`Una recuperación que avanzaba muy bien`,paragraphs:[`Patán continuaba evolucionando favorablemente después de la cirugía.`,`Todavía debía utilizar collar isabelino para evitar que pudiera tocarse la zona operada, pero su recuperación avanzaba muy bien.`,`Ya se encontraba viviendo bajo techo, acompañado y recibiendo todos los cuidados necesarios.`]},{date:`2026-05-22`,title:`El control veterinario salió muy bien`,paragraphs:[`Patán volvió a control y los profesionales lo encontraron muy bien.`,`El proceso postquirúrgico continuaba evolucionando favorablemente y el foco comenzaba a pasar de la urgencia médica a completar su recuperación.`,`En esa publicación la rescatista informó que la deuda veterinaria general ascendía aproximadamente a $1.500.000, además de los gastos de alimentación de los animales bajo cuidado.`]},{date:`2026-05-20`,title:`Cada día un poco más fuerte`,paragraphs:[`Dos días después de la cirugía, Patán ya mostraba una recuperación muy favorable.`,`Comenzaba a relacionarse con otros animales, estaba más cómodo y seguía demostrando un excelente ánimo.`,`También se recibían donaciones de alimento de buena calidad para ayudarlo a recuperar peso después de todo lo que había atravesado.`]},{date:`2026-05-19`,title:`Patán volvió a nacer`,paragraphs:[`Después de años sobreviviendo en la calle y de llegar con una fractura expuesta que llevaba varios días sin tratamiento adecuado, Patán finalmente había podido ser operado.`,`La amputación permitió dejar atrás una lesión que ya no podía recuperarse y comenzar un camino completamente nuevo.`,`Después de la cirugía se encontraba tranquilo, cuidado y con ganas de seguir adelante.`,`En esta publicación se informó una deuda veterinaria general de $1.456.217 y también una entrega de $53.000 para continuar reduciendo los gastos acumulados.`]},{date:`2026-05-18`,title:`La cirugía salió bien`,paragraphs:[`Se realizó finalmente la cirugía de Patán.`,`Durante la intervención se amputó el miembro inferior izquierdo, se retiró uno de los balines alojados en su cuerpo, se extrajo una masa encontrada durante los controles y también fue castrado.`,`La masa extraída fue enviada a analizar para obtener más información. En las publicaciones aportadas no aparece posteriormente informado el resultado de ese análisis.`,`La cirugía salió bien y, durante la tarde, Patán ya había comido mientras continuaba bajo seguimiento veterinario.`,`Antes de incorporar el costo de la cirugía, internación, medicación y controles posteriores, las publicaciones mencionaban una deuda veterinaria general cercana a $1.006.000.`]},{date:`2026-05-17`,title:`Todo listo para la operación`,paragraphs:[`Los estudios necesarios para avanzar con la cirugía habían dado resultados favorables.`,`La amputación estaba programada para el día siguiente y se pidió acompañamiento para Patán antes de uno de los momentos más importantes de su recuperación.`]},{date:`2026-05-16`,title:`La cirugía ya tenía fecha`,paragraphs:[`Patán continuaba con controles, curaciones y cambios de vendaje mientras esperaba la cirugía.`,`También se habían realizado ecografía, placas y análisis. En los estudios podía observarse además otro balín alojado en su cuerpo.`,`Los resultados permitieron confirmar que se encontraba en condiciones de ser operado y la cirugía de amputación quedó programada para el lunes 18 de mayo.`,`En las distintas publicaciones de ese día se informaron montos generales de deuda cercanos al millón de pesos. Después de una entrega de $100.000 se publicó un saldo de $1.006.617, todavía sin incluir el costo de la cirugía.`]},{date:`2026-05-11`,title:`Análisis y estudios antes de la cirugía`,paragraphs:[`Patán tuvo un nuevo control veterinario, cambio de vendaje y extracción de sangre para realizar análisis.`,`Continuaba tomando antibióticos por vía oral y comenzaba poco a poco a incorporar alimento balanceado.`,`Durante la revisión también encontraron una pequeña masa que debía continuar siendo estudiada.`,`Antes de fijar definitivamente la fecha de la cirugía todavía era necesario realizar una ecografía y completar los estudios prequirúrgicos.`]},{date:`2026-05-10`,title:`Collar isabelino y nuevos controles`,paragraphs:[`Durante los primeros días de recuperación Patán necesitó utilizar collar isabelino porque intentaba lamer algunas de sus heridas.`,`La prioridad seguía siendo mantener la zona protegida, continuar con las curaciones y completar los análisis necesarios antes de la operación.`]},{date:`2026-05-09`,title:`Por primera vez durmió dentro de una casa`,paragraphs:[`Después del rescate, Patán pasó su primera noche dentro de una casa y pudo dormir sobre un sillón.`,`En el control veterinario se encontraba un poco deshidratado, por lo que necesitó suero. Recibió además antibióticos y una alimentación especial para complementar su dieta mientras recuperaba fuerzas.`,`Los profesionales lo encontraron mucho mejor y Patán comenzaba a descubrir las caricias, los mimos y la sensación de estar cuidado.`,`En ese momento las publicaciones indicaban que la deuda veterinaria general rondaba los $900.000.`]},{date:`2026-05-08`,title:`Patán finalmente pudo salir de debajo de las chapas`,paragraphs:[`Después de varios pedidos de ayuda se consiguió un lugar de tránsito y también se logró coordinar el traslado de Patán hasta la veterinaria.`,`Había permanecido al menos cinco días sobreviviendo con una lesión gravísima después de haber sido mordido por otro perro.`,`La evaluación veterinaria confirmó una fractura expuesta con infección en el hueso, balines o perdigones debajo de la piel, una fractura antigua mal consolidada y varias piezas dentales dañadas por golpes anteriores.`,`El diagnóstico para la pata lesionada fue contundente: una vez que estuviera suficientemente estable sería necesario amputarla para salvarle la vida.`,`A pesar del dolor y de todo lo que había vivido, Patán todavía movía la cola cuando alguien lo acariciaba.`]},{date:`2026-05-07`,title:`Un galgo herido necesitaba ayuda urgente`,paragraphs:[`Una vecina pidió ayuda por un galgo adulto de aproximadamente 4 años que se encontraba refugiado debajo de unas chapas en el barrio La Unión.`,`Había sido mordido por otro perro y llevaba varios días con una lesión grave en una de sus patas. La vecina intentaba alimentarlo y darle antibióticos, pero necesitaba atención veterinaria urgente.`,`La primera necesidad fue conseguir un tránsito donde pudiera permanecer seguro y recuperarse después de recibir atención.`,`Ese pedido de ayuda fue el comienzo de la historia de Patán.`]}],updatedAt:`2026-06-01`,seoDescription:`Conocé la historia de Patán, un galgo rescatado con una fractura expuesta e infección que logró recuperarse después de una cirugía de amputación.`},{slug:`gina`,name:`Gina`,statuses:[`memorial`],featured:!1,summary:`Gina era una gata feral que fue atropellada en Av. Don Bosco. Después de varias horas de búsqueda lograron encontrarla gravemente herida en una cuneta y trasladarla a la veterinaria. A pesar de todos los esfuerzos por estabilizarla, falleció dos días después.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787519723/WhatsApp_Image_2026-08-23_at_18.04.07.jpg`,width:1200,height:1600,alt:`Gina durante su internación veterinaria`,objectPosition:`center`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787519722/WhatsApp_Image_2026-08-23_at_18.04.07_1.jpg`,width:1200,height:1600,alt:`Gina luego de ser rescatada`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787519722/WhatsApp_Image_2026-08-23_at_18.04.07_2.jpg`,width:1200,height:1600,alt:`Gina recibiendo atención veterinaria`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787519722/WhatsApp_Image_2026-08-23_at_18.04.08.jpg`,width:1200,height:1600,alt:`Gina durante su internación`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787519722/WhatsApp_Image_2026-08-23_at_18.04.07_3.jpg`,width:1200,height:1600,alt:`Gina durante su internación`}],story:[`Gina era una gata feral que sobrevivía en la zona de Av. Don Bosco.`,`Su historia comenzó cuando fue atropellada por un auto que, según la información difundida durante el rescate, estaba corriendo picadas.`,`Después del impacto logró alejarse del lugar. Durante varias horas estuvieron buscándola hasta que finalmente pudieron encontrarla gravemente herida dentro de una cuneta.`,`Estaba sola, mojada, embarrada y prácticamente sin poder movilizarse. A pesar del estado en el que se encontraba, había conseguido arrastrarse hasta allí después del atropello.`,`Jesi fue una de las personas que ayudó a que su historia no terminara en aquella cuneta: la vio, difundió el pedido de ayuda y permaneció en el lugar hasta que pudieron llegar para rescatarla.`,`Una vez encontrada fue trasladada de urgencia a la veterinaria para intentar estabilizarla. Desde ese momento dejó de ser solamente una gata feral herida en la calle. Recibió un nombre: Gina.`,`La evaluación veterinaria mostró un cuadro extremadamente delicado. Presentaba una fractura de columna, no lograba regular correctamente su temperatura corporal y apenas conservaba pequeños reflejos.`,`Gina quedó internada mientras el equipo veterinario intentaba estabilizarla y evaluar si existía alguna posibilidad de recuperación.`,`Durante los dos días siguientes se hizo todo lo posible para darle esa oportunidad, pero la gravedad de las lesiones que había sufrido terminó siendo demasiado grande.`,`Su organismo comenzó a dejar de responder. Gina no reaccionaba a los estímulos, no podía orinar ni defecar y no fue posible conseguir que regulara su temperatura corporal.`,`Finalmente, Gina falleció.`,`No fue posible cambiar el desenlace de su historia, pero sí algo fundamental: aquella cuneta fría, mojada y solitaria no terminó convirtiéndose en su tumba.`,`Durante sus últimas horas hubo personas a su lado. Recibió atención veterinaria, cuidados y una mano amiga que decidió no dejarla sola.`,`Gina tuvo una oportunidad. Durante dos días hubo personas intentando salvarla y acompañándola hasta el último momento.`,`Su paso fue breve, pero dejó una de esas historias que recuerdan por qué ayudar sigue importando incluso cuando un rescate no consigue el final que todos esperaban.`],currentNeeds:[],updates:[{date:`2026-05-01`,title:`El rescate de Gina`,paragraphs:[`Gina era una gata feral que fue atropellada en Av. Don Bosco por un vehículo que, según la información difundida durante el rescate, estaba corriendo picadas.`,`Después del impacto logró desplazarse y durante varias horas estuvieron buscándola.`,`Finalmente pudieron encontrarla dentro de una cuneta. Estaba gravemente herida, mojada, embarrada y prácticamente sin poder movilizarse.`,`Jesi la vio, difundió el pedido de ayuda y permaneció en el lugar hasta que pudieron llegar para rescatarla.`,`Una vez encontrada fue trasladada de urgencia a la veterinaria para intentar estabilizarla.`]},{date:`2026-05-01`,title:`Un cuadro extremadamente delicado`,paragraphs:[`Después del rescate recibió el nombre de Gina.`,`La evaluación veterinaria mostró que presentaba una fractura de columna.`,`Su estado era muy delicado: no conseguía regular correctamente su temperatura corporal y apenas conservaba pequeños reflejos.`,`Gina quedó internada para intentar estabilizarla y continuar evaluando su evolución.`,`A pesar del pronóstico, se decidió darle todas las oportunidades posibles.`]},{date:`2026-05-02`,title:`Gina no resistió`,paragraphs:[`Después de dos días de lucha, Gina no pudo resistir la gravedad de las heridas sufridas.`,`Dejó de responder a los estímulos, no orinaba ni defecaba y en ningún momento se consiguió regular su temperatura corporal.`,`Finalmente falleció.`,`La tristeza y la impotencia fueron enormes, pero quedó el consuelo de saber que aquella cuneta fría y solitaria no terminó siendo su tumba.`,`Durante sus últimas horas Gina estuvo acompañada, recibió atención veterinaria y hubo personas intentando darle una oportunidad hasta el último momento.`]}],updatedAt:`2026-05-02`,seoDescription:`Conocé la historia de Gina, una gata feral atropellada en Av. Don Bosco que fue rescatada de una cuneta y recibió atención veterinaria durante sus últimos días.`},{slug:`rafa`,name:`Rafa`,statuses:[`memorial`],featured:!1,summary:`Rafa fue encontrado atropellado en Bolívar al 500. Llegó a la veterinaria en estado crítico, con múltiples fracturas, hipotermia y un fuerte traumatismo. A pesar de los esfuerzos por estabilizarlo, su cuadro se agravó durante el mismo día y falleció acompañado.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787520343/WhatsApp_Image_2026-08-23_at_18.16.43.jpg`,width:1200,height:1600,alt:`Rafa durante su internación veterinaria`,objectPosition:`center`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1787520343/WhatsApp_Image_2026-08-23_at_18.16.42.jpg`,width:1200,height:1600,alt:`Rafa recibiendo atención veterinaria luego de su rescate`}],story:[`Rafa fue encontrado atropellado durante la mañana del 23 de abril de 2026 en Bolívar al 500, en Tandil.`,`El caso comenzó a difundirse buscando ayuda y también intentando encontrar a sus posibles dueños. Era un gato macho, sin castrar y que se veía bien alimentado, por lo que existía la posibilidad de que tuviera una familia que lo estuviera buscando.`,`David Villoslada no dudó en acercarse para socorrerlo. Rafa fue retirado del lugar y recibió una primera asistencia antes de ser derivado inmediatamente a Clínica San Lorenzo debido a la gravedad de sus heridas.`,`El accidente le había provocado lesiones muy importantes. Presentaba la lengua cortada, fractura de mandíbula, fractura de cadera e hipotermia. Además tenía una gran cantidad de pulgas y durante la evaluación detectaron un soplo cardíaco.`,`Rafa quedó internado y con oxígeno mientras intentaban estabilizarlo. Las primeras 24 horas eran consideradas fundamentales y su estado era extremadamente delicado.`,`Durante las primeras horas existió la esperanza de que pudiera superar el momento más crítico, pero con el transcurso de la tarde su cuadro comenzó a complicarse.`,`Los estudios mostraron además que había sufrido un golpe muy fuerte en la cabeza y que tenía la vejiga fisurada. La lesión de la vejiga podía ser operada, pero su estado general era tan grave que someterlo a una cirugía en ese momento no era posible.`,`A pesar de los esfuerzos realizados para estabilizarlo, Rafa finalmente falleció ese mismo día.`,`Su historia fue muy corta, pero no terminó solo en el lugar donde había sido atropellado. David estuvo pendiente de él desde el rescate y, después de su fallecimiento, volvió a buscarlo para poder darle una despedida digna.`,`No se pudo cambiar el desenlace, pero sí acompañarlo. Rafa recibió atención, cuidados y personas que hicieron todo lo posible por darle una oportunidad hasta el último momento.`,`Rafita no murió solo en un pasto frío. Durante sus últimas horas hubo personas luchando por él, y su historia quedó marcada por quienes decidieron detenerse y ayudarlo.`],currentNeeds:[],updates:[{date:`2026-04-23`,title:`Rafa llega de urgencia a la veterinaria`,paragraphs:[`Durante la mañana encontraron a Rafa atropellado en Bolívar al 500.`,`Era un gato macho sin castrar y se veía bien alimentado, por lo que también comenzó la búsqueda de posibles dueños.`,`David Villoslada acudió a socorrerlo. Después de una primera asistencia, Rafa fue derivado inmediatamente a Clínica San Lorenzo debido a la gravedad de sus heridas.`,`Presentaba la lengua cortada, fractura de mandíbula, fractura de cadera e hipotermia.`,`También tenía una gran cantidad de pulgas y durante la evaluación detectaron un soplo en el corazón.`,`Su estado era muy grave. Quedó internado y con oxígeno mientras intentaban estabilizarlo. Las primeras 24 horas iban a ser cruciales.`]},{date:`2026-04-23`,title:`Su cuadro se complica`,paragraphs:[`Durante las primeras horas existía la esperanza de que Rafa pudiera estabilizarse, pero con el transcurso de la tarde su estado empeoró.`,`Además de las lesiones inicialmente observadas, presentaba un golpe muy fuerte en la cabeza y una fisura en la vejiga.`,`La lesión de la vejiga era operable, pero debido a la extrema gravedad de su estado una cirugía en ese momento no era posible.`,`El equipo veterinario continuó intentando estabilizarlo.`]},{date:`2026-04-23`,title:`Hasta siempre, Rafita`,paragraphs:[`Lamentablemente Rafa no logró resistir las graves lesiones provocadas por el atropello y falleció.`,`Aunque el desenlace fue doloroso, no estuvo solo. Desde el momento en que fue encontrado hubo personas intentando darle una oportunidad.`,`David, que había ido a buscarlo y estuvo pendiente de su evolución, volvió después para poder enterrarlo y darle una despedida digna.`,`No pudimos cambiar el final de su historia, pero Rafa estuvo acompañado hasta el último momento.`]}],updatedAt:`2026-04-23`,seoDescription:`Conocé la historia de Rafa, un gato encontrado atropellado en Bolívar al 500 que recibió atención veterinaria de urgencia y fue acompañado hasta el final.`},{slug:`matilda`,name:`Matilda`,statuses:[`recovering`,`closed`],featured:!1,summary:`Matilda llegó con apenas dos meses de vida, menos de un kilo de peso y un cuadro severo de sarna sarcóptica asociado a defensas muy bajas. Con tratamiento, buena alimentación y los cuidados de su tránsito logró recuperarse por completo y encontró una familia.`,coverImage:{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1788008637/WhatsApp_Image_2026-08-23_at_19.39.20_1.jpg`,width:1600,height:900,alt:`Matilda recuperada después de su tratamiento`,objectPosition:`50% 40%`},gallery:[{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1788008637/WhatsApp_Image_2026-08-23_at_19.39.20.jpg`,width:900,height:1600,alt:`Matilda durante sus primeros días de tratamiento`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1788008637/WhatsApp_Image_2026-08-23_at_19.39.19.jpg`,width:900,height:1600,alt:`Matilda recuperándose de la sarna sarcóptica`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1788008637/WhatsApp_Image_2026-08-23_at_19.39.20_2.jpg`,width:900,height:1600,alt:`Matilda completamente recuperada`},{src:`https://res.cloudinary.com/r7yd5dny/image/upload/v1788008637/WhatsApp_Image_2026-08-23_at_19.39.20_3.jpg`,width:900,height:1600,alt:`Matilda disfrutando de su nueva vida`}],story:[`Matilda llegó a comienzos de marzo con apenas unos dos meses de vida y menos de un kilo de peso. A pesar de ser tan pequeña, ya había tenido que conocer el dolor.`,`Fue diagnosticada con sarna sarcóptica, un cuadro poco frecuente en gatos que, en su caso, estaba acompañado por un sistema inmune tremendamente debilitado. La picazón era intensa y al rascarse se había lastimado la piel.`,`Aun atravesando todo eso, Matilda era una gatita muy mimosa, activa y con muy buen apetito. Comenzó su tratamiento y quedó al cuidado de Mica, quien decidió transitarla y acompañarla durante la recuperación.`,`Además del tratamiento veterinario, necesitaba una alimentación de muy buena calidad para recuperar peso y fortalecer sus defensas. Poco a poco empezó a mejorar y, apenas unos días después, el cambio ya era notable: su piel evolucionaba favorablemente y su ánimo estaba excelente.`,`Con el paso de las semanas Matilda consiguió recuperarse completamente. Volvió a tener la energía propia de una cachorra, se mostró sociable con otros gatos, fue desparasitada y comenzó a dejar atrás definitivamente aquellos primeros días tan difíciles.`,`Su historia terminó de la mejor manera: después de recuperarse, Matilda encontró una familia. La pequeña que había llegado enferma, con las defensas por el piso y necesitando ayuda para salir adelante pudo comenzar una nueva etapa rodeada de cuidados y amor.`],currentNeeds:[],updates:[{date:`2026-03-21`,title:`Matilda está recuperada y encontró una familia`,paragraphs:[`Después de varias semanas de tratamiento y cuidados, Matilda logró recuperarse completamente de la sarna con la que había llegado.`,`La pequeña estaba llena de vida y energía, se llevaba muy bien con otros gatos y disfrutaba de cosas tan simples como jugar con cajas y dormir en la cama.`,`También ya había sido desparasitada. Como parte de esta nueva etapa, debía continuar con su correspondiente plan de vacunación y una buena alimentación.`,`La publicación confirmó además la noticia más esperada: Matilda encontró una familia y pudo cerrar definitivamente la etapa más difícil de su historia.`]},{date:`2026-03-07`,title:`Una evolución enorme en pocos días`,paragraphs:[`Apenas unos días después de iniciar el tratamiento, Matilda se encontraba muchísimo mejor de la sarna.`,`Su ánimo era excelente: se mostraba muy activa, juguetona y curiosa. Incluso al salir de la veterinaria quería observar todo lo que ocurría a su alrededor.`,`En ese momento continuaba necesitando controles, medicación y alimentación de buena calidad para fortalecer sus defensas y seguir recuperándose.`,`En esta actualización la rescatista informó una deuda veterinaria general de $656.271. Ese monto incluía gastos de distintos rescates, entre ellos cirugía y controles de Feli, atención, medicación y controles de Matilda, además de alimento para animales que se encontraban en tránsito.`]},{date:`2026-03-03`,title:`Matilda ingresó con apenas dos meses y sarna sarcóptica`,paragraphs:[`Matilda ingresó a la veterinaria con aproximadamente dos meses de vida y menos de un kilo de peso.`,`Fue diagnosticada con sarna sarcóptica. Según se informó en ese momento, se trataba de un cuadro muy poco frecuente en gatos y evidenciaba que su sistema inmune se encontraba muy debilitado.`,`La picazón le provocaba mucho malestar y se había lastimado al rascarse. A pesar de eso, Matilda era muy mimosa y conservaba un excelente apetito.`,`Comenzó tratamiento veterinario y quedó bajo el cuidado de Mica durante su tránsito. Las primeras 48 horas eran importantes para observar cómo respondía al tratamiento.`,`Además necesitaba alimentación de muy buena calidad y alimento de recuperación para ganar peso y ayudar a fortalecer sus defensas.`]}],updatedAt:`2026-03-21`,seoDescription:`Conocé la historia de Matilda, una gatita rescatada con apenas dos meses y un cuadro de sarna sarcóptica que logró recuperarse completamente y encontrar una familia.`}];var m=class o{cases=p;getBySlug(a){return this.cases.find(e=>e.slug===a)}getFeatured(){return this.cases.filter(a=>a.featured)}getByStatus(a){return a===`all`?this.cases:this.cases.filter(e=>e.statuses.includes(a))}static ɵfac=function(e){return new(e||o)};static ɵprov=O({token:o,factory:o.ɵfac,providedIn:`root`})};export{m as t};